final class ParserParityTests: XCTestCase {
    /// The Swift parser must match redtooth/intent.py on every fixture (generated by tools/make_intent_fixtures.py).
    func testMatchesDesktopParser() throws {
        let url = try XCTUnwrap(Bundle.module.url(forResource: "intent_fixtures", withExtension: "json"))
        let fx = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? JSONObject)
        let iso = ISO8601DateFormatter()
        iso.formatOptions = [.withInternetDateTime]
        let nowStr = try XCTUnwrap(fx.str("now"))
        let now = try XCTUnwrap(iso.date(from: nowStr))
        let tz = try XCTUnwrap(TimeZone(secondsFromGMT: -6 * 3600)) // fixtures use 2026-11-24T15:30-06:00
        let names = (fx.arr("names") as? [String]) ?? []
        var mismatches: [String] = []
        for case let c as JSONObject in fx.arr("cases") ?? [] {
            let text = c.str("text")!
            let i = IntentParser.parse(text, knownNames: names, now: now, timeZone: tz)
            var diffs: [String] = []
            func cmp(_ k: String, _ got: Any?, _ want: Any?) { if !same(got, want) { diffs.append("\(k): got \(String(describing: got)) want \(String(describing: want))") } }
            cmp("action", i.action, c["action"]); cmp("person", i.person, c["person"]); cmp("pronoun", i.pronoun, c["pronoun"])
            cmp("relation", i.relation, c["relation"]); cmp("device_kind", i.deviceKind, c["device_kind"]); cmp("device_hint", i.deviceHint, c["device_hint"])
            cmp("choice", i.choice, c["choice"]); cmp("instead", i.instead, c["instead"])
            if let f = c["file"] as? JSONObject {
                guard let q = i.file else { diffs.append("file: missing"); mismatches.append("“\(text)” " + diffs.joined(separator: "; ")); continue }
                cmp("kinds", q.kinds, f["kinds"]); cmp("exts", q.exts.sorted(), f["exts"]); cmp("topic", q.topic, f["topic"])
                cmp("since", q.since, f["since"]); cmp("until", q.until, f["until"]); cmp("time_label", q.timeLabel, f["time_label"])
                cmp("refers_previous", q.refersPrevious, f["refers_previous"]); cmp("names", q.names, f["names"])
            } else if i.file != nil { diffs.append("file: unexpected") }
            if !diffs.isEmpty { mismatches.append("“\(text)” " + diffs.joined(separator: "; ")) }
        }
        XCTAssertEqual(mismatches, [], mismatches.joined(separator: "\n"))
    }

    private func same(_ a: Any?, _ b: Any?) -> Bool {
        let bNil = b == nil || b is NSNull
        guard let a else { return bNil }
        switch (a, b) {
        case let (x as String, y as String): return x == y
        case let (x as Bool, y as Bool): return x == y
        case let (x as Bool, y as NSNumber): return x == y.boolValue
        case let (x as Int, y as NSNumber): return x == y.intValue
        case let (x as Double, y as NSNumber): return abs(x - y.doubleValue) < 1e-3
        case let (x as [String], y as [Any]): return x == y.compactMap { $0 as? String } && x.count == y.count
        default: return false
        }
    }
}

final class PhonesTests: XCTestCase {
    func testNormalizationAndHashesMatchDesktop() {
        let expected = ["(555) 014-2000": ("+15550142000", "2c5f5762ea8a2911"), "+44 20 7946 0958": ("+442079460958", "14f6459315e84598"),
                        "0049 30 1234567": ("+49301234567", "7f6a8bcfa4ab7486"), "15550100": ("+115550100", "d3fa465069710934")]
        for (raw, (norm, hash)) in expected {
            XCTAssertEqual(Phones.normalize(raw), norm, raw)
            XCTAssertEqual(String(Phones.hash(raw).prefix(16)), hash, raw)
        }
    }

    func testCountryRulesMatchDesktop() throws {
        let url = try XCTUnwrap(Bundle.module.url(forResource: "phone_fixtures", withExtension: "json"))
        let fx = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? JSONObject)
        var bad: [String] = []
        for case let c as JSONObject in fx.arr("cases") ?? [] {
            let got = Phones.normalize(c.str("raw")!, country: c.str("country"))
            if got != c.str("e164") { bad.append("\(c.str("raw")!) (\(c.str("country")!)): \(got) != \(c.str("e164")!)") }
        }
        XCTAssertEqual(bad, [])
        let table = (fx.arr("countries") ?? []).compactMap { $0 as? JSONObject }.map { [$0.str("iso")!, $0.str("cc")!, $0.str("trunk")!, $0.str("idd")!] }
        XCTAssertEqual(countries.map { [$0.iso, $0.cc, $0.trunk, $0.idd] }, table)
    }

    func testRankingAndQuestionsMatchDesktop() throws {
        let url = try XCTUnwrap(Bundle.module.url(forResource: "ranking_fixtures", withExtension: "json"))
        let fx = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? JSONObject)
        let now = Date(timeIntervalSince1970: try XCTUnwrap(fx.dbl("now")))
        let utc = TimeZone(identifier: "UTC")!
        for case let c as JSONObject in fx.arr("coverage") ?? [] {
            let got = Ranking.coverageBonus((c.arr("qws") as? [String]) ?? [], name: c.str("name")!, chunk: c.str("chunk")!)
            XCTAssertEqual(got, c.dbl("bonus")!, accuracy: 1e-6, c.str("name")!)
        }
        func hits(_ a: Any?) -> [FileHit] {
            ((a as? [Any]) ?? []).compactMap { $0 as? JSONObject }.map { h in
                var f = FileHit(id: "1", path: h.str("path")!, name: h.str("name")!, kind: "document", ext: h.str("ext")!, size: 1, mtime: h.dbl("mtime")!, score: h.dbl("score")!)
                f.confidence = h.dbl("confidence"); f.reasons = (h.arr("reasons") as? [String]) ?? []
                return f
            }
        }
        for case let q as JSONObject in fx.arr("questions") ?? [] {
            let hs = hits(q["hits"])
            XCTAssertEqual(Clarify.distinguish(hs, now: now, timeZone: utc).0, q.str("question"))
            XCTAssertEqual(hs.map { Clarify.optionDetail($0, now: now, timeZone: utc) }, (q.arr("details") as? [String]) ?? [])
        }
        for case let a as JSONObject in fx.arr("ambiguous") ?? [] {
            XCTAssertEqual(Clarify.ambiguous(hits(a["hits"]), hasTopic: a.bool("topic")!), a.bool("ask")!)
        }
    }

    func testUsageFadesAndRemembersPicks() {
        var clock = 1_000_000.0
        let u = UsageStore(now: { clock })
        u.record("/d/sent.docx", kind: "sent")
        u.recordPick("term paper", path: "/d/final.docx")
        let s1 = u.signals(["/d/sent.docx", "/d/final.docx", "/d/never.docx"], query: "Term Papers")
        XCTAssertGreaterThan(s1["/d/sent.docx"]!.0, 0)
        XCTAssertGreaterThan(s1["/d/final.docx"]!.1, 0)
        XCTAssertEqual(s1["/d/never.docx"]!.0, 0)
        clock += 60 * 86400
        XCTAssertLessThan(u.signals(["/d/sent.docx"])["/d/sent.docx"]!.0, s1["/d/sent.docx"]!.0 / 4)
    }

    func testDifflibRatio() { XCTAssertEqual((PeopleResolver.ratio("daniel", "danielle") * 1000).rounded(), 857) }
}

// MARK: - Transfers

final class TransferTests: XCTestCase {
    func tmp() -> URL {
        let u = FileManager.default.temporaryDirectory.appendingPathComponent("rt-" + UUID().uuidString)
        try! FileManager.default.createDirectory(at: u, withIntermediateDirectories: true)
        return u
    }

    func sha(_ u: URL) -> String { sha256Hex(try! Data(contentsOf: u)) }

    func testSwiftToSwiftOverLAN() async throws {
        let dir = tmp()
        let src = dir.appendingPathComponent("Deck.pptx")
        try Data((0..<(6 << 20)).map { UInt8(truncatingIfNeeded: $0 &* 31) }).write(to: src)
        let rx = Receiver(deviceId: "dev", deviceName: "iPhone", inbox: dir.appendingPathComponent("in"), acceptor: { _ in true })
        let l = LANListener()
        try l.start(receiver: rx, port: 0)
        defer { l.stop() }
        let s = Sender(meName: "Alex", mePhone: "+15550100")
        let t = s.start(FileSource(url: src), recipientFirst: "Dan", device: Device(id: "dev", name: "iPhone", kind: "phone", endpoints: [Endpoint(kind: "lan", host: "127.0.0.1", port: l.port)]))
        await s.wait(t.id)
        XCTAssertEqual(t.status, "saved", t.error)
        XCTAssertEqual(sha(dir.appendingPathComponent("in/Deck.pptx")), sha(src))
        XCTAssertNotNil(t.timings["accept_to_first_byte_ms"])
    }

    func testDeclineIsReported() async throws {
        let dir = tmp()
        let src = dir.appendingPathComponent("a.txt")
        try Data("hi".utf8).write(to: src)
        let rx = Receiver(deviceId: "dev", deviceName: "iPhone", inbox: dir.appendingPathComponent("in"), acceptor: { _ in false })
        let l = LANListener()
        try l.start(receiver: rx, port: 0)
        defer { l.stop() }
        let s = Sender(meName: "Alex", mePhone: "+1")
        let t = s.start(FileSource(url: src), recipientFirst: "Dan", device: Device(id: "dev", name: "iPhone", kind: "phone", endpoints: [Endpoint(kind: "lan", host: "127.0.0.1", port: l.port)]))
        await s.wait(t.id)
        XCTAssertEqual(t.label, "Declined")
    }
}

// MARK: - Agent with fakes

final class FakeFiles: FileSearch, @unchecked Sendable {
    var docs: [(URL, String)] = []
    func add(_ dir: URL, _ name: String, _ text: String, _ mtime: Date) {
        let u = dir.appendingPathComponent(name)
        try! Data(repeating: 7, count: 4096).write(to: u)
        try! FileManager.default.setAttributes([.modificationDate: mtime], ofItemAtPath: u.path)
        docs.append((u, text))
    }
    private func hit(_ u: URL, _ score: Double) -> FileHit {
        let m = (try? u.resourceValues(forKeys: [.contentModificationDateKey]).contentModificationDate?.timeIntervalSince1970) ?? 0
        return FileHit(id: u.path, path: u.path, name: u.lastPathComponent, kind: "", ext: "." + u.pathExtension, size: 4096, mtime: m, score: score)
    }
    func search(_ q: FileQuery) -> [FileHit] {
        let words = q.topic.lowercased().split(separator: " ").map(String.init).filter { $0.count > 2 }.map { $0.hasSuffix("s") ? String($0.dropLast()) : $0 }
        let scored: [(FileHit, Double)] = docs.compactMap { (u, text) in
            let h = hit(u, 0)
            if !q.exts.isEmpty && !q.exts.contains(h.ext) { return nil }
            if let s = q.since, h.mtime < s { return nil }
            if let s = q.until, h.mtime >= s { return nil }
            let hay = (u.lastPathComponent + " " + text).lowercased()
            let sc = words.isEmpty ? 1 : Double(words.filter { hay.contains($0) }.count) / Double(words.count)
            return sc > 0 ? (h, sc) : nil
        }.sorted { ($0.1, $0.0.mtime) > ($1.1, $1.0.mtime) }
        let top = scored.first?.1 ?? 1
        return scored.map { var h = $0.0; h.score = $0.1 / top; return h }
    }
    func recent(_ n: Int) -> [FileHit] { Array(docs.map { hit($0.0, 1) }.sorted { $0.mtime > $1.mtime }.prefix(n)) }
    func source(_ hit: FileHit) -> FileSource? { FileSource(url: URL(fileURLWithPath: hit.path)) }
    func indexing() -> (done: Int, queued: Int, complete: Bool)? { nil }
}

final class FakeAudio: AudioPort, @unchecked Sendable {
    var out = (name: "iPhone", bluetooth: false)
    func currentOutput() -> (name: String, bluetooth: Bool) { out }
}

final class MemoryAudio: AudioMemory, @unchecked Sendable {
    var map: [String: String] = [:]
    func remember(ownerPhone: String?, ownerName: String, outputName: String) { map[ownerPhone ?? ownerName] = outputName }
    func lookup(ownerPhone: String?) -> String? { ownerPhone.flatMap { map[$0] } }
}

final class AgentTests: XCTestCase {
    struct World {
        let agent: Agent
        let dir: URL
        let audio: FakeAudio
        let memory: MemoryAudio
        let directory: MemoryDirectory
        let listeners: [LANListener]
    }

    func world(registered: Bool = true) async throws -> World {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("rt-agent-" + UUID().uuidString)
        try FileManager.default.createDirectory(at: dir.appendingPathComponent("docs"), withIntermediateDirectories: true)
        let phoneRx = Receiver(deviceId: "d_phone", deviceName: "Daniel's Pixel", inbox: dir.appendingPathComponent("daniel-phone"), acceptor: { _ in true })
        let laptopRx = Receiver(deviceId: "d_laptop", deviceName: "Daniel's MacBook Air", inbox: dir.appendingPathComponent("daniel-laptop"), acceptor: { _ in true })
        let l1 = LANListener(), l2 = LANListener()
        try l1.start(receiver: phoneRx, port: 0); try l2.start(receiver: laptopRx, port: 0)
        let directory = MemoryDirectory()
        if registered {
            directory.register(phone: "+15550142000", name: "Daniel Ortiz")
            try await directory.setDevices(phone: "+15550142000", devices: [
                Device(id: "d_phone", name: "Daniel's Pixel", kind: "phone", model: "Pixel 9", hasApp: true, endpoints: [Endpoint(kind: "lan", host: "127.0.0.1", port: l1.port)]),
                Device(id: "d_laptop", name: "Daniel's MacBook Air", kind: "laptop", model: "MacBook Air", hasApp: true, endpoints: [Endpoint(kind: "lan", host: "127.0.0.1", port: l2.port)]),
                Device(id: "bt:xm5", name: "WH-1000XM5", kind: "headphones", address: "88:C9:E8:12:34:56", model: "Sony WH-1000XM5", shortModel: "Sony XM5s"),
            ])
        }
        let files = FakeFiles()
        let now = Date()
        var cal = Calendar.current; cal.timeZone = .current
        var morning = cal.date(bySettingHour: min(9, max(0, cal.component(.hour, from: now) - 1)), minute: 12, second: 0, of: now)!
        if morning > now { morning = now.addingTimeInterval(-2400) }
        files.add(dir.appendingPathComponent("docs"), "Q4 Board Update.pptx", "revenue pipeline hiring board", morning)
        files.add(dir.appendingPathComponent("docs"), "Sales Kickoff 2027.pptx", "territories quotas partner program", min(now.addingTimeInterval(-60), morning.addingTimeInterval(300)))
        files.add(dir.appendingPathComponent("docs"), "Retention Plan.pptx", "keeping more customers renewals cancellations churn", now.addingTimeInterval(-3 * 86400))
        let me = Person(contact: Contact(id: "c_me", name: "Alex Rivera", phones: ["+15550100"]), isSelf: true)
        let people = PeopleResolver(contacts: [
            Contact(id: "c_daniel", name: "Daniel Ortiz", phones: ["+15550142000"], nicknames: ["Dan"], relation: "friend", lastInteraction: 1),
            Contact(id: "c_dkim", name: "Daniel Kim", phones: ["+15550188000"], relation: "coworker"),
        ], me: me)
        let audio = FakeAudio(), memory = MemoryAudio()
        let agent = Agent(me: me, people: people, directory: directory, files: files, audio: audio, audioMemory: memory, sender: Sender(meName: "Alex Rivera", mePhone: "+15550100"))
        await agent.refreshPeople()
        people.nearbyPhones = ["+15550142000"]
        return World(agent: agent, dir: dir, audio: audio, memory: memory, directory: directory, listeners: [l1, l2])
    }

    func testSendDeckEditedThisMorningAsksThenDelivers() async throws {
        let w = try await world()
        defer { w.listeners.forEach { $0.stop() } }
        let r = await w.agent.ask("Send Daniel the deck I edited this morning.")
        XCTAssertEqual(r.question?.kind, "choose_file")
        XCTAssertEqual(Set(r.question!.options.map(\.label)), ["Q4 Board Update", "Sales Kickoff 2027"])
        XCTAssertEqual(r.person?.name, "Daniel Ortiz") // not Daniel Kim
        let r2 = await w.agent.ask("the Q4 board one")
        XCTAssertTrue(r2.text.contains("Q4 Board Update.pptx") && r2.text.contains("Pixel"), r2.text)
        let id = try XCTUnwrap(r2.transferId)
        await w.agent.sender.wait(id)
        XCTAssertEqual(w.agent.sender.transfer(id)?.status, "saved", w.agent.sender.transfer(id)?.error)
    }

    func testSendItToHisLaptopInstead() async throws {
        let w = try await world()
        defer { w.listeners.forEach { $0.stop() } }
        _ = await w.agent.ask("Send Daniel the deck I edited this morning")
        let first = await w.agent.ask("2").files.first?.name ?? ""
        let r = await w.agent.ask("Send it to his laptop instead.")
        XCTAssertTrue(r.ok && r.text.contains("MacBook Air") && r.text.contains(first) && r.text.hasSuffix("instead."), r.text)
        await w.agent.sender.wait(r.transferId!)
        XCTAssertEqual(w.agent.sender.transfer(r.transferId!)?.status, "saved")
    }

    func testFindDeckAboutCustomerChurn() async throws {
        let w = try await world()
        defer { w.listeners.forEach { $0.stop() } }
        let r = await w.agent.ask("Find the deck about customer churn.")
        XCTAssertEqual(r.files.first?.name, "Retention Plan.pptx")
    }

    func testHeadphonesOnIPhoneNameTheDeviceAndNudgeOwner() async throws {
        let w = try await world()
        defer { w.listeners.forEach { $0.stop() } }
        let r = await w.agent.ask("Hey, connect to my friend Daniel's headphones")
        XCTAssertEqual(r.action, .showRoutePicker(hint: "Sony XM5s"))
        XCTAssertTrue(r.text.contains("pairing mode") && r.text.contains("notification"), r.text)
        XCTAssertEqual(w.directory.inboxes.values.flatMap { $0 }.first?.str("type"), "pairing_mode")
        // The user picks them in the route picker; next time Redtooth just points at them.
        w.audio.out = (name: "WH-1000XM5", bluetooth: true)
        w.agent.noteRouteChanged()
        w.audio.out = (name: "iPhone", bluetooth: false)
        let r2 = await w.agent.ask("connect to Daniel's headphones")
        XCTAssertEqual(r2.action, .showRoutePicker(hint: "WH-1000XM5"))
        XCTAssertEqual(r2.text, "Choose WH-1000XM5 in the audio menu.")
    }
}

// MARK: - Interop with the Python desktop (macOS `swift test` from this repo)

#if os(macOS)
final class InteropTests: XCTestCase {
    func repoRoot() throws -> URL {
        var u = URL(fileURLWithPath: #filePath)
        while u.path != "/" {
            u.deleteLastPathComponent()
            if FileManager.default.fileExists(atPath: u.appendingPathComponent("redtooth/transfer/protocol.py").path) { return u }
        }
        throw XCTSkip("desktop repo not found")
    }

    func python(_ args: [String]) throws -> (Process, Pipe) {
        let p = Process(), out = Pipe()
        p.executableURL = URL(fileURLWithPath: "/usr/bin/env")
        p.arguments = [ProcessInfo.processInfo.environment["REDTOOTH_PY"] ?? "python3"] + args
        p.currentDirectoryURL = try repoRoot()
        p.standardOutput = out
        try p.run()
        return (p, out)
    }

    func firstLine(_ pipe: Pipe) -> String? {
        var buf = Data()
        while true {
            let b = pipe.fileHandleForReading.readData(ofLength: 1)
            if b.isEmpty { return buf.isEmpty ? nil : String(decoding: buf, as: UTF8.self) }
            if b == Data("\n".utf8) { return String(decoding: buf, as: UTF8.self) }
            buf.append(b)
        }
    }

    func testSwiftPhoneSendsToPythonDesktop() async throws {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("rt-ia-" + UUID().uuidString)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        let (p, out) = try python(["tools/interop_peer.py", "receive", dir.appendingPathComponent("in").path])
        defer { p.terminate() }
        let hello = try XCTUnwrap(firstLine(out).flatMap { try? JSONSerialization.jsonObject(with: Data($0.utf8)) as? JSONObject })
        let src = dir.appendingPathComponent("From iPhone.pdf")
        try Data((0..<(3 << 20)).map { UInt8(truncatingIfNeeded: $0 % 251) }).write(to: src)
        let s = Sender(meName: "Swift phone", mePhone: "+15550142000")
        let t = s.start(FileSource(url: src), recipientFirst: "Desktop", device: Device(id: "py_desktop", name: "Python desktop", kind: "laptop",
                                                                                         endpoints: [Endpoint(kind: "lan", host: "127.0.0.1", port: hello.int("port") ?? 0)]))
        await s.wait(t.id)
        XCTAssertEqual(t.status, "saved", t.error)
    }

    func testPythonDesktopSendsToSwiftPhone() async throws {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("rt-ib-" + UUID().uuidString)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        let rx = Receiver(deviceId: "s_phone", deviceName: "Swift phone", inbox: dir.appendingPathComponent("in"), acceptor: { _ in true })
        let l = LANListener()
        try l.start(receiver: rx, port: 0)
        defer { l.stop() }
        let src = dir.appendingPathComponent("From desktop.bin")
        try Data((0..<(5 << 20)).map { UInt8(truncatingIfNeeded: $0 &* 13) }).write(to: src)
        let (p, out) = try python(["tools/interop_peer.py", "send", src.path, "127.0.0.1", String(l.port), "s_phone"])
        p.waitUntilExit()
        let res = try XCTUnwrap(String(decoding: out.fileHandleForReading.readDataToEndOfFile(), as: UTF8.self).split(separator: "\n").last
            .flatMap { try? JSONSerialization.jsonObject(with: Data($0.utf8)) as? JSONObject })
        XCTAssertEqual(res.str("status"), "saved")
        XCTAssertEqual(sha256Hex(try Data(contentsOf: dir.appendingPathComponent("in/From desktop.bin"))), sha256Hex(try Data(contentsOf: src)))
    }
}
#endif
